/** Original authored mesh assemblies, separate from the flow/sensor logic.
 * Generated by tools/generate_valves.py; keep movable pivots independent.
 */
import * as THREE from 'three';
import {GLTFLoader} from 'three/addons/loaders/GLTFLoader.js';
const TYPES=new Set(['ball','gate','butterfly','control']);
const loader=new GLTFLoader(),cache=new Map();
export function loadValveModel(type){
 if(!TYPES.has(type))return Promise.reject(new Error('Invalid valve type: '+type));
 if(!cache.has(type)){
   const url=new URL('../assets/valves/'+type+'.glb',import.meta.url).href;
   cache.set(type,loader.loadAsync(url).catch(e=>{cache.delete(type);throw e;}));
 }
 return cache.get(type).then(gltf=>assemble(gltf.scene,type));
}
function assemble(template,type){
 const root=template.clone(true);
 // Each instance owns geometry/material and can be disposed after regeneration.
 root.traverse(obj=>{
  if(!obj.isMesh)return;
  obj.geometry=obj.geometry.clone();
  obj.material=Array.isArray(obj.material)?obj.material.map(m=>m.clone()):obj.material.clone();
  obj.receiveShadow=true;
 });
 const handle=new THREE.Group();handle.name='valve_actuator_pivot';
 handle.position.z={ball:.177,gate:.255,butterfly:.181,control:.250}[type];
 handle.userData.pivotHeight=handle.position.z;
 const disc=new THREE.Group();disc.name='valve_disc_pivot';
 const movable=[];
 root.traverse(obj=>{
  if(!obj.isMesh)return;
  if(obj.name.startsWith('actuator_'))movable.push([obj,handle]);
  else if(obj.name.startsWith('disc_'))movable.push([obj,disc]);
 });
 if(!movable.some(([,p])=>p===handle))throw new Error('Missing valve actuator: '+type);
 if(type==='butterfly'&&!movable.some(([,p])=>p===disc))throw new Error('Missing butterfly disc mesh');
 for(const [part,parent] of movable){
  part.parent.remove(part);
  part.position.set(0,0,0);part.quaternion.identity();part.scale.set(1,1,1);
  parent.add(part);
 }
 root.add(handle);
 if(type==='butterfly')root.add(disc);
 return {root,handle,disc:type==='butterfly'?disc:null};
}